func (o Order) Value() (driver.Value, error) { return json.Marshal(o) }

func (o *Order) Scan(src any) error {
    if src == nil { return nil }               // NULL column: leave the zero value
    b, ok := src.([]byte)
    if !ok { return fmt.Errorf("order: cannot scan %T", src) }
    return json.Unmarshal(b, o)
}
